-- 문자셋: utf8mb4 (한글 + 이모지)
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `items`;
DROP TABLE IF EXISTS `employees`;
DROP TABLE IF EXISTS `depts`;
DROP TABLE IF EXISTS `floors`;
DROP TABLE IF EXISTS `seating_meta`;

CREATE TABLE `floors` (
  `id`   VARCHAR(32)  NOT NULL,
  `name` VARCHAR(32)  NOT NULL,
  `w`    INT          NOT NULL,
  `h`    INT          NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `depts` (
  `id`    VARCHAR(32)  NOT NULL,
  `name`  VARCHAR(100) NOT NULL,
  `color` VARCHAR(20)  DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `employees` (
  `id`   VARCHAR(40)  NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `dept` VARCHAR(100) DEFAULT NULL,
  `rank` VARCHAR(50)  DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_emp_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `items` (
  `id`         VARCHAR(40) NOT NULL,
  `floor_id`   VARCHAR(32) NOT NULL,
  `type`       VARCHAR(16) NOT NULL,
  `x`          INT NOT NULL,
  `y`          INT NOT NULL,
  `w`          INT NOT NULL,
  `h`          INT NOT NULL,
  `z`          INT NOT NULL DEFAULT 0,
  `seat_no`    VARCHAR(32)  DEFAULT NULL,
  `name`       VARCHAR(100) DEFAULT NULL,
  `dept_id`    VARCHAR(32)  DEFAULT NULL,
  `title`      VARCHAR(50)  DEFAULT NULL,
  `occupied`   TINYINT(1)   DEFAULT NULL,
  `fill`       VARCHAR(20)  DEFAULT NULL,
  `stroke`     VARCHAR(20)  DEFAULT NULL,
  `sw`         INT          DEFAULT NULL,
  `line`       TINYINT(1)   DEFAULT NULL,
  `icon`       VARCHAR(16)  DEFAULT NULL,
  `label`      VARCHAR(100) DEFAULT NULL,
  `ip`         VARCHAR(32)  DEFAULT NULL,
  `text`       VARCHAR(255) DEFAULT NULL,
  `color`      VARCHAR(20)  DEFAULT NULL,
  `font_size`  INT          DEFAULT NULL,
  `bold`       TINYINT(1)   DEFAULT NULL,
  `orient`     CHAR(1)      DEFAULT NULL,
  `thickness`  INT          DEFAULT NULL,
  `line_style` VARCHAR(16)  DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_items_floor` (`floor_id`),
  KEY `idx_items_type` (`type`),
  KEY `idx_items_name` (`name`),
  KEY `idx_items_dept` (`dept_id`),
  CONSTRAINT `fk_items_floor` FOREIGN KEY (`floor_id`) REFERENCES `floors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_items_dept`  FOREIGN KEY (`dept_id`)  REFERENCES `depts` (`id`)  ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `seating_meta` (
  `k` VARCHAR(40)  NOT NULL,
  `v` VARCHAR(255) DEFAULT NULL,
  PRIMARY KEY (`k`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


